const snapshotFileReadable = `-- name: SnapshotFileReadable :one
SELECT EXISTS(SELECT 1 FROM module_revision_steps s JOIN modules m ON m.org_id=s.org_id AND m.id=s.module_id
LEFT JOIN module_revision_pins p ON p.org_id=m.org_id AND p.module_id=m.id AND p.user_id=$1
WHERE s.org_id=$2 AND s.file_id=$3 AND m.archived_at IS NULL AND m.published_at IS NOT NULL
AND s.revision_id=COALESCE(p.revision_id,m.published_revision_id))::boolean
`

type SnapshotFileReadableParams struct {
	UserID uuid.UUID
	OrgID  uuid.UUID
	FileID uuid.NullUUID
}

func (q *Queries) SnapshotFileReadable(ctx context.Context, arg SnapshotFileReadableParams) (bool, error) {
	row := q.db.QueryRow(ctx, snapshotFileReadable, arg.UserID, arg.OrgID, arg.FileID)
	var column_1 bool
	err := row.Scan(&column_1)
	return column_1, err
}

const snapshotModuleSteps = `-- name: SnapshotModuleSteps :execrows
INSERT INTO module_revision_steps(org_id,module_id,revision_id,id,position,kind,title,body,rich_content,file_id,video_id,quiz_id,quiz_revision_id,minutes)
SELECT s.org_id,s.module_id,$1,s.id,s.position,s.kind,s.title,s.body,s.rich_content,s.file_id,s.video_id,s.quiz_id,z.published_revision_id,s.minutes
FROM module_steps s LEFT JOIN quizzes z ON z.org_id=s.org_id AND z.id=s.quiz_id
WHERE s.org_id=$2 AND s.module_id=$3 AND s.archived_at IS NULL
`

type SnapshotModuleStepsParams struct {
	RevisionID uuid.UUID
	OrgID      uuid.UUID
	ModuleID   uuid.UUID
}

func (q *Queries) SnapshotModuleSteps(ctx context.Context, arg SnapshotModuleStepsParams) (int64, error) {
	result, err := q.db.Exec(ctx, snapshotModuleSteps, arg.RevisionID, arg.OrgID, arg.ModuleID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}
